using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Text.RegularExpressions;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Verse;using WarEconomy.WorkerBridge;using HarmonyLib;using UnityEngine;
namespace QAAuthority {
 public static class Fields {
  public static string NextPath="";public static string LastInjection="";
  static JToken Changed(JToken v){if(v.Type==JTokenType.Integer)return new JValue(v.Value<long>()+1);if(v.Type==JTokenType.Float)return new JValue(v.Value<double>()+0.125);if(v.Type==JTokenType.Boolean)return new JValue(!v.Value<bool>());return new JValue(v.Value<string>()+"_QA");}
  public static object Arm(string path){NextPath=path;return new{armed=path};}
  public static object Status(){var b=UnityEngine.Object.FindObjectOfType<WorkerBridgeComponent>();var f=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;var wanted=new[]{"currentGeneration","currentResultEpoch","trustedSimulationReady","semanticState","registeredAuthority","sealedResult","lastStagedPath","lastStagedSha","activeGrant","currentStageValidationReceipt"};return wanted.ToDictionary(x=>x,x=>b.GetType().GetField(x,f)?.GetValue(b));}
  public static object Matrix(){var baseline=EngineHostCensus.GenerateCensus(Find.Maps[0]);var j=JObject.Parse(baseline.ToJson());var chosen=new Dictionary<string,JToken>();
   foreach(var v in j.Descendants().Where(x=>x is JValue&&x.Type!=JTokenType.Null)){string path=Regex.Replace(v.Path,@"\[\d+\]","[*]");path=Regex.Replace(path,@"^(defCounts|classCounts|stackTotals)\..+$","$1.*");path=Regex.Replace(path,@"\.skills\..+$",".skills.*");if(!chosen.ContainsKey(path))chosen[path]=v;}
   var rows=new List<object>();string bh=baseline.ComputeManifestHash();foreach(var pair in chosen){var clone=(JObject)j.DeepClone();var target=clone.SelectToken(pair.Value.Path);var before=target.DeepClone();var changed=Changed(target);target.Replace(changed);var c=clone.ToObject<CensusManifestData>();var compare=EngineHostCensus.CompareCensus(baseline,c);rows.Add(new{field=pair.Key,path=pair.Value.Path,before,after=changed,hashBefore=bh,hashAfter=c.ComputeManifestHash(),hashChanged=bh!=c.ComputeManifestHash(),comparatorPass=compare.isPass,errors=compare.errors});}return new{rows,baselineHash=bh,fields=typeof(CensusManifestData).Assembly.GetTypes().Where(t=>t.Namespace=="WarEconomy.WorkerBridge"&&new[]{"CensusManifestData","ContainerRecord","ContainedItemRecord","PawnRecord","HediffRecordV3","RelationRecordV3","AnimalRecord","BuildingRecord","BillRecordV3","ZoneRecord","DesignationRecord","ConditionRecord","FireRecordV3","PlantRecordV3","ReservationRecord","GlobalDependencyRecord","AuthorityBundle","ResultManifest"}.Contains(t.Name)).ToDictionary(t=>t.Name,t=>t.GetFields(BindingFlags.Public|BindingFlags.Instance).Select(x=>new{name=x.Name,type=x.FieldType.ToString()}).ToArray())};}
  public static void Inject(ref CensusManifestData result){if(NextPath=="")return;string path=NextPath;NextPath="";var obj=JObject.Parse(result.ToJson());var token=obj.SelectToken(path);if(token==null)throw new Exception("QA census path missing: "+path);var before=token.DeepClone();var changed=Changed(token);token.Replace(changed);result=obj.ToObject<CensusManifestData>();LastInjection=JsonConvert.SerializeObject(new{path,before,after=changed,hash=result.ComputeManifestHash()});}
 }
 [HarmonyPatch(typeof(EngineHostCensus),nameof(EngineHostCensus.GenerateCensus))]public static class CensusInjection {static void Postfix(ref CensusManifestData __result){Fields.Inject(ref __result);}}
}
